            'id',
            'data.product_id',
            'data.id',
            'product.id',
            'product.product_id',
            'result.id',
            'result.product_id',
        ];

        foreach ($candidate_paths as $candidate_path) {
            $candidate_id = Arr::get($backup_payload, $candidate_path);
            if (is_numeric($candidate_id) && (int) $candidate_id > 0) {
                return (int) $candidate_id;
            }
        }

        return 0;
