class CreateProductImportBatch extends CreateRecord
{
    private const array REQUIRED_SHEETS = [
        'Product',
        'Description',
        'Image',
        'Product Category',
        'Product Attribute',
        'Seo Url',
        'Special',
        'Discount',
    ];

    private const array REQUIRED_HEADERS = [
        'Product' => [
            'Product Id',
