                'failed_items'    => $failed_rows,
                'last_error'      => $audit_metadata['last_error'],
                'error_log_path'  => $audit_metadata['error_log_path'],
            ]);
        } catch (Throwable $e) {
            Log::channel('stack')->error($e->getMessage(), $e->getTrace());

            $this->markBatchFailed($batch, $e->getMessage(), $e);
        }
    }

