        $ean                 = Str::trim((string) ($unique_values['ean'] ?? ''));

        $candidate_sets = [];

        if ($external_product_id !== '') {
            $candidate_sets['external_product_id'] = ProductShop::query()
                ->where('shop_id', $resolved_shop_id)
                ->where('external_product_id', $external_product_id)
                ->pluck('product_id')
