declare(strict_types=1);

namespace Opencart\Catalog\Controller\Api\Product;

use Exception;
use JetBrains\PhpStorm\NoReturn;
use Opencart\Catalog\Model\Api\Product\Product as ApiProductModel;
use Opencart\System\Engine\Loader;
use Opencart\System\Library\Language;
use Opencart\System\Library\Log;
use Opencart\System\Library\Request;
use Opencart\System\Library\Response;
use Opencart\System\Library\Session;

class Product
{
	private ApiProductModel $model_api_product_product;
	private array           $json = [];

	/**
	 * @throws Exception
	 */
	public function __construct(
		private readonly Loader   $load,
		private readonly Session  $session,
		private readonly Language $language,
		private readonly Log      $log,
		private readonly Request  $request,
		private readonly Response $response,
	) {
		$this->load->language('api/product/product');

		$this->model_api_product_product = app(ApiProductModel::class);

		if (empty($this->session->get('api_id'))) {
			$this->json['error_invalid_token'] = $this->language->get('error_invalid_token');
		}
	}

	/**
	 * @return void
	 * @throws Exception
	 */
	#[NoReturn]
	public function takeProducts(): void
	{
		if ($this->json) {
			$this->response->sendJson($this->json);

			return;
		}

		if (!$this->request->post->has('take_products')) {
			$this->json['error'] = $this->language->get('error_take_products');
		} else if (!$this->request->post->has('limit_start')) {
			$this->json['error'] = $this->language->get('error_limit_start');
		} else if (!$this->request->post->has('limit_offset')) {
			$this->json['error'] = $this->language->get('error_limit_offset');
		} else {
			$start  = (int)$this->request->post->get('limit_start');
			$offset = (int)$this->request->post->get('limit_offset');

			$this->json['products'] = $this->model_api_product_product->getProducts($start, $offset);

			$this->json['success'] = sprintf($this->language->get('text_success_take_products'), $offset, $start);

			$message = 'take_products: ' . print_r($this->request->post->get('take_products'), true) . PHP_EOL . $this->json['success'];

			$this->log->write(
				message   : $message,
				error_type: 'info'
			);
		}

		if (isset($this->json['error'])) {
			$this->log->write($this->json['error']);
		}

		$this->response->sendJson($this->json);
	}

	/**
	 * @return void
	 * @throws Exception
	 */
	#[NoReturn]
	public function takeTotalNumberProducts(): void
	{
		if ($this->json) {
			$this->response->sendJson($this->json);

			return;
		}

		if (!$this->request->post->has('take_total_number_products')) {
			$this->json['error'] = $this->language->get('error_take_total_number_products');
		} else {
			$this->json['total_products'] = $this->model_api_product_product->getTotalNumberProducts();

			$this->json['success'] = sprintf($this->language->get('text_success_take_total_number_products'), $this->json['total_products']);

			$message = 'ake_total_number_products: ' . print_r($this->request->post->get('take_total_number_products'), true) . PHP_EOL . $this->json['success'];

			$this->log->write(
				message   : $message,
				error_type: 'info'
			);
		}

		if (isset($this->json['error'])) {
			$this->log->write($this->json['error']);
		}

		$this->response->sendJson($this->json);
	}
