<?php

declare(strict_types=1);

namespace Opencart\System\Library\DB;

use Doctrine\DBAL\Connection;
use Doctrine\DBAL\DriverManager;
use Doctrine\DBAL\Exception as DoctrineException;
use Doctrine\DBAL\Result;
use Exception;
use Generator;
use Opencart\System\Library\Dto\Db\QueryDto;
use Opencart\System\Library\Log;
use Opencart\System\Library\SqlHelper;
use PDO;
use Throwable;

class Doctrine
{
	private ?Connection $connection = null;
	private int         $affected   = 0;

	/**
	 * @throws Exception
	 */
	public function __construct(string $hostname, string $username, string $password, string $database, int $port = 0)
	{
		if ($port <= 0) {
			$port = 3306;
		}

		try {
			$this->connection = DriverManager::getConnection([
				'dbname'        => $database,
				'driver'        => 'pdo_mysql',
				'host'          => $hostname,
				'password'      => $password,
				'port'          => $port,
				'user'          => $username,
				'charset'       => 'utf8mb4',
				'driverOptions' => [
					PDO::ATTR_PERSISTENT => false,
				],
			]);

			$this->query("SET SESSION sql_mode = 'NO_ZERO_IN_DATE,NO_ENGINE_SUBSTITUTION'");
			$this->safeQuery('SET `time_zone` = ?', date('P'));
		} catch (DoctrineException $e) {
			throw new Exception('Error: ' . $e->getMessage(), (int)$e->getCode(), $e);
		}
	}

	/**
	 * This method not to preparing data for query from user!!!
	 *
	 * @throws Exception
	 */
	public function query(string $sql): bool|QueryDto
	{
