 21		public function createProductFromPayload(array $payload): int
 22		{
 23			$product = $payload['product'] ?? null;
 24	
 25			if (!is_array($product)) {
 26				throw new RuntimeException('Product payload is missing');
 27			}
 28	
 29			$db_prefix    = (string)env('DB_PREFIX');
 30			$language_map = $this->resolveLanguageMap($db_prefix);
 31	
 32			$model = $this->normalizeText((string)($product['model'] ?? ''));
 33			$sku   = $this->normalizeText((string)($product['sku'] ?? ''));
 34			$ean   = $this->normalizeText((string)($product['ean'] ?? ''));
 35	
 36			if ($model === '') {
 37				$model = 'API-' . time();
 38			}
 39	
 40			$quantity          = max(0, (int)($product['quantity'] ?? 0));
 41			$minimum           = max(1, (int)($product['minimum'] ?? 1));
 42			$price             = (float)($product['price'] ?? 0);
 43			$image             = $this->makeProductImagePath((string)($product['image'] ?? ''));
 44			$status            = (int)((bool)($product['is_active'] ?? false));
 45			$date_available    = $this->normalizeDate((string)($product['date_available'] ?? ''));
 46			$date_added        = $this->normalizeDate((string)($product['date_added'] ?? ''));
 47			$date_modified     = $this->normalizeDate((string)($product['date_modified'] ?? ''));
 48			$manufacturer_name = oc_strtolower($this->normalizeText($product['manufacturer_brand']['manufacturer'] ?? ''));
 49			$manufacturer_id   = 0;
 50	
 51			if ($manufacturer_name !== '') {
 52				$sql = "
 53					SELECT * FROM {$db_prefix}manufacturer 
 54						WHERE LCASE(`name`) = ?
 55				";
 56	
 57				$query = $this->db->safeQuery($sql, $manufacturer_name);
 58	
 59				$manufacturer_id = (int)($query->getRow('manufacturer_id') ?? 0);
 60			}
 61	
 62			$bind_params = [
 63				$model,
 64				$sku,
 65				$ean,
 66				$quantity,
 67				$image,
 68				$manufacturer_id,
 69				$price,
 70				$date_available,
 71				$minimum,
 72				$status,
 73				$date_added,
 74				$date_modified,
 75			];
 76	
 77			$sql = "
 78				INSERT INTO {$db_prefix}product (`model`, `sku`, `ean`, `quantity`, `image`, `manufacturer_id`, `price`, `date_available`, `minimum`, `status`, `date_added`, `date_modified`) 
 79				VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
 80			";
 81	
 82			$this->db->safeQuery($sql, $bind_params);
 83	
 84			$product_id = $this->db->getLastId();
 85	
 86			if ($product_id <= 0) {
 87				throw new RuntimeException('Failed to create product and resolve product_id');
 88			}
 89	
 90			$sql = "INSERT INTO {$db_prefix}product_to_store (`product_id`, `store_id`) VALUES (?, ?)";
 91	
 92			$this->db->safeQuery($sql, [
 93				$product_id,
 94				$this->config->getStoreId()
 95			]);
 96	
 97			$sql = "INSERT INTO {$db_prefix}product_to_layout (`product_id`, `store_id`) VALUES (?, ?)";
 98	
 99			$this->db->safeQuery($sql, [
100				$product_id,
101				$this->config->getStoreId()
102			]);
103	
104			$this->insertDescriptions($db_prefix, $product_id, $payload, $language_map, $model);
105			$this->insertProductImages($db_prefix, $product_id, $payload, $image);
106			$this->insertProductCategories($db_prefix, $product_id, $payload, $language_map);
107			$this->insertProductAttributes($db_prefix, $product_id, $payload, $language_map);
108			$this->insertSeoUrls($db_prefix, $product_id, $payload, $language_map);
109	
110			return $product_id;
111		}
