131		 *
132		 * @return int[]
133		 * @throws Exception
134		 */
135		private function resolveLanguageMap(string $db_prefix): array
136		{
137			$result = [
138				'uk-ua' => LanguageConstants::UA_LANGUAGE_ID,
139				'uk_ua' => LanguageConstants::UA_LANGUAGE_ID,
140				'uk'    => LanguageConstants::UA_LANGUAGE_ID,
141				'en-gb' => LanguageConstants::EN_LANGUAGE_ID,
142				'en_gb' => LanguageConstants::EN_LANGUAGE_ID,
143				'en'    => LanguageConstants::EN_LANGUAGE_ID,
144				'ru-ru' => LanguageConstants::RU_LANGUAGE_ID,
145				'ru_ru' => LanguageConstants::RU_LANGUAGE_ID,
146				'ru'    => LanguageConstants::RU_LANGUAGE_ID,
147				'de-de' => LanguageConstants::DE_LANGUAGE_ID,
148				'de_de' => LanguageConstants::DE_LANGUAGE_ID,
149				'de'    => LanguageConstants::DE_LANGUAGE_ID,
150			];
151	
152			$query = $this->db->query("SELECT language_id, code FROM {$db_prefix}language");
153	
154			foreach ($query->getRows() as $row) {
155				$language_id = (int)($row['language_id'] ?? 0);
156				$code        = $this->normalizeLanguageCode((string)($row['code'] ?? ''));
157	
158				if ($language_id <= 0 || $code === '') {
159					continue;
160				}
161	
162				$result[$code] = $language_id;
163	
164				$short_code = explode('-', $code)[0] ?? '';
165				if ($short_code !== '') {
166					$result[$short_code] = $language_id;
167				}
168			}
169	
170			return $result;
171		}
