183		private function insertDescriptions(string $db_prefix, int $product_id, array $payload, array $language_map, string $fallback_name): void
184		{
185			$sql          = "INSERT INTO {$db_prefix}product_description (`product_id`, `language_id`, `name`, `description`, `meta_title`, `meta_description`, `meta_keyword`) VALUES ";
186			$descriptions = $payload['descriptions'] ?? [];
187	
188			if (!is_array($descriptions) || $descriptions === []) {
189				$default_language_id = (int)($language_map['uk'] ?? LanguageConstants::UA_LANGUAGE_ID);
190	
191				$sql .= '
192					VALUES (?, ?, ?, ?, ?, ?, ?)
193				';
