205				$this->db->safeQuery($sql, $bind_params);
206	
207				return;
208			}
209	
210			$sqls                 = [];
211			$sql_bind_placeholder = '(?, ?, ?, ?, ?, ?, ?)';
212			$bind_params          = [];
213	
214			foreach ($descriptions as $description) {
215				if (!is_array($description)) {
216					continue;
217				}
218	
219				$language_code = $this->normalizeLanguageCode((string)($description['shop_language_code'] ?? ''));
