236				}
237	
238				$description_text = $this->normalizeText((string)($description['description'] ?? ''));
239				$meta_title       = $this->normalizeText((string)($description['meta_title'] ?? ''));
240				$meta_description = $this->normalizeText((string)($description['meta_description'] ?? ''));
241				$meta_keywords    = $this->normalizeText((string)($description['meta_keywords'] ?? ''));
