256				]);
257			}
258	
259			if (!empty($sqls)) {
260				$sql .= implode(', ', $sqls);
261	
262				$this->db->safeQuery($sql, $bind_params);
263			} else {
264				$this->log->warning('No valid descriptions to insert for product', [
