	private function resolveManufacturerId(string $db_prefix, array $manufacturer_brand): int
	{
		$external_manufacturer_id = (int)($manufacturer_brand['external_manufacturer_id'] ?? 0);
		if ($external_manufacturer_id > 0) {
			$query = $this->db->safeQuery(
				' SELECT `manufacturer_id` FROM ' . $db_prefix . 'manufacturer WHERE `manufacturer_id` = ?',
				$external_manufacturer_id
			);
			if ((int)($query->getRow('manufacturer_id') ?? 0) > 0) {
				return $external_manufacturer_id;
			}
		}

		$manufacturer_name = oc_strtolower($this->normalizeText((string)($manufacturer_brand['manufacturer'] ?? '')));
		if ($manufacturer_name === '') {
			return 0;
		}

		$query = $this->db->safeQuery(
			' SELECT `manufacturer_id` FROM ' . $db_prefix . 'manufacturer WHERE LCASE(`name`) = ? ORDER BY `manufacturer_id` LIMIT 2',
			$manufacturer_name
		);
		$manufacturer_ids = array_map(static fn (array $row): int => (int)$row['manufacturer_id'], $query->getRows());
		if (count($manufacturer_ids) > 1) {
			throw new RuntimeException('Manufacturer name matches multiple OpenCart manufacturers');
		}

		return $manufacturer_ids[0] ?? 0;
	}

	private function validateProductFieldLength(string $field_name, string $value, int $max_length): void
	{
		if (mb_strlen($value, 'UTF-8') > $max_length) {
			throw new RuntimeException('Product ' . $field_name . ' exceeds the OpenCart limit of ' . $max_length . ' characters');
		}
	}

	private function normalizeBoolean(mixed $value): bool
	{
		return filter_var($value, FILTER_VALIDATE_BOOLEAN);
	}

	private function ensureProductStoreAndLayout(string $db_prefix, int $product_id): void
	{
		$store_id = (int)$this->config->getStoreId();
		$store_query = $this->db->safeQuery(
			' SELECT `product_id` FROM ' . $db_prefix . 'product_to_store WHERE `product_id` = ? AND `store_id` = ?',
			[$product_id, $store_id]
		);
		if ($store_query->getNumRows() === 0) {
			$this->db->safeQuery(
				'INSERT INTO ' . $db_prefix . 'product_to_store (`product_id`, `store_id`) VALUES (?, ?)',
				[$product_id, $store_id]
			);
		}

		$layout_query = $this->db->safeQuery(
			' SELECT `product_id` FROM ' . $db_prefix . 'product_to_layout WHERE `product_id` = ? AND `store_id` = ?',
			[$product_id, $store_id]
		);
		if ($layout_query->getNumRows() === 0) {
			$this->db->safeQuery(
				'INSERT INTO ' . $db_prefix . 'product_to_layout (`product_id`, `store_id`) VALUES (?, ?)',
				[$product_id, $store_id]
			);
		}
	}

	private function deleteProductRelations(string $db_prefix, int $product_id): void
	{
		foreach (['product_description', 'product_image', 'product_to_category', 'product_attribute', 'product_special', 'product_discount'] as $table) {
			$this->db->safeQuery('DELETE FROM ' . $db_prefix . $table . ' WHERE `product_id` = ?', $product_id);
		}

		$this->db->safeQuery(
			' DELETE FROM ' . $db_prefix . 'seo_url WHERE `store_id` = ? AND `key` = ? AND `value` = ?',
			[(int)$this->config->getStoreId(), 'product_id', (string)$product_id]
		);
	}

	/**
	 * @param string $image_name
	 *
	 * @return string
	 */
	private function makeProductImagePath(string $image_name): string
	{
		$image_name = $this->normalizeText($image_name);

		if ($image_name === '') {
			return '';
		}

		if (str_starts_with($image_name, ImageConstants::PATH_TO_PRODUCT_IMAGES)) {
			return $image_name;
		}

		return ImageConstants::PATH_TO_PRODUCT_IMAGES . ltrim($image_name, '/');
	}

	/**
	 * @param string $db_prefix
	 *
	 * @return int[]
	 * @throws Exception
	 */
	private function resolveLanguageMap(string $db_prefix): array
	{
		$result = [
			'uk-ua' => LanguageConstants::UA_LANGUAGE_ID,
			'uk_ua' => LanguageConstants::UA_LANGUAGE_ID,
			'uk'    => LanguageConstants::UA_LANGUAGE_ID,
			'en-gb' => LanguageConstants::EN_LANGUAGE_ID,
			'en_gb' => LanguageConstants::EN_LANGUAGE_ID,
			'en'    => LanguageConstants::EN_LANGUAGE_ID,
			'ru-ru' => LanguageConstants::RU_LANGUAGE_ID,
			'ru_ru' => LanguageConstants::RU_LANGUAGE_ID,
			'ru'    => LanguageConstants::RU_LANGUAGE_ID,
			'de-de' => LanguageConstants::DE_LANGUAGE_ID,
			'de_de' => LanguageConstants::DE_LANGUAGE_ID,
			'de'    => LanguageConstants::DE_LANGUAGE_ID,
		];

		$query = $this->db->query("SELECT language_id, code FROM {$db_prefix}language");

		foreach ($query->getRows() as $row) {
			$language_id = (int)($row['language_id'] ?? 0);
			$code        = $this->normalizeLanguageCode((string)($row['code'] ?? ''));

			if ($language_id <= 0 || $code === '') {
				continue;
			}

			$result[$code] = $language_id;

			$short_code = explode('-', $code)[0] ?? '';
			if ($short_code !== '') {
				$result[$short_code] = $language_id;
			}
		}

		return $result;
	}

	/**
	 * @param string $db_prefix
	 * @param int    $product_id
	 * @param array  $payload
	 * @param array  $language_map
	 * @param string $fallback_name
	 *
	 * @return void
	 * @throws Exception
	 */
	private function insertDescriptions(string $db_prefix, int $product_id, array $payload, array $language_map, string $fallback_name): void
	{
		$descriptions = $payload['descriptions'] ?? [];
		$descriptions_by_language = [];

		foreach (is_array($descriptions) ? $descriptions : [] as $description) {
			if (!is_array($description)) {
				continue;
			}

			$language_code = $this->normalizeLanguageCode((string)($description['shop_language_code'] ?? ''));
			$language_id   = (int)($language_map[$language_code] ?? 0);

			if ($language_id <= 0) {
				$this->log->warning("Can't find language_id!", [
					'product_id'          => $product_id,
					'external_product_id' => $payload['product']['id'] ?? null,
					'model'               => $payload['product']['model'] ?? null,
					'language_code'       => $language_code,
				]);

				continue;
			}

			$name = $this->normalizeText((string)($description['name'] ?? ''));
			if ($name === '') {
				$name = $fallback_name;
			}

			$description_text = $this->normalizeText((string)($description['description'] ?? ''));
			$meta_title       = $this->normalizeText((string)($description['meta_title'] ?? ''));
			$meta_description = $this->normalizeText((string)($description['meta_description'] ?? ''));
			$meta_keywords    = $this->normalizeText((string)($description['meta_keywords'] ?? ''));

			if ($meta_title === '') {
				$meta_title = $name;
			}

			$descriptions_by_language[$language_id] = [
				$product_id,
				$language_id,
				$name,
				$description_text,
				$meta_title,
				$meta_description,
				$meta_keywords,
			];
		}

		if ($descriptions_by_language === []) {
			$default_language_id = (int)($language_map['uk'] ?? LanguageConstants::UA_LANGUAGE_ID);
			$descriptions_by_language[$default_language_id] = [
				$product_id,
				$default_language_id,
				$fallback_name,
				'',
				$fallback_name,
				'',
				'',
			];
		}

		$placeholders = implode(', ', array_fill(0, count($descriptions_by_language), '(?, ?, ?, ?, ?, ?, ?)'));
		$bind_params  = array_merge(...array_values($descriptions_by_language));
		$this->db->safeQuery(
			'INSERT INTO ' . $db_prefix . 'product_description (`product_id`, `language_id`, `name`, `description`, `meta_title`, `meta_description`, `meta_keyword`) VALUES ' . $placeholders,
			$bind_params
		);
	}

	/**
	 * @param string $db_prefix
	 * @param int    $product_id
	 * @param array  $payload
	 * @param string $main_image
	 *
	 * @return void
	 * @throws Exception
	 */
	private function insertProductImages(string $db_prefix, int $product_id, array $payload, string $main_image): void
	{
		$images = $payload['images'] ?? [];

		if (!is_array($images) || $images === []) {
			return;
		}

		$sql             = "INSERT INTO {$db_prefix}product_image (`product_id`, `image`, `sort_order`) VALUES ";
		$sqls            = [];
		$sql_placeholder = '(?, ?, ?)';
		$bind_params     = [];

		foreach ($images as $image_row) {
			if (!is_array($image_row)) {
				continue;
			}

			$image = $this->makeProductImagePath((string)($image_row['image'] ?? ''));
			if ($image === '' || $image === $main_image) {
				continue;
			}
			$this->validateProductFieldLength('image', $image, 255);

			$sort_order = (int)($image_row['sort_order'] ?? 1);

			$sqls[]      = $sql_placeholder;
			$bind_params = array_merge($bind_params, [
				$product_id,
				$image,
				$sort_order,
			]);
		}

		if (!empty($sqls)) {
			$sql .= implode(', ', $sqls);

			$this->db->safeQuery($sql, $bind_params);
		} else {
			$this->log->warning('No valid additional images to insert for product', [
				'product_id'          => $product_id,
				'external_product_id' => $payload['product']['id'] ?? null,
				'model'               => $payload['product']['model'] ?? null,
				'images'              => $payload['images'] ?? null,
			]);
		}
	}

	/**
	 * @param string $db_prefix
	 * @param int    $product_id
	 * @param array  $payload
	 * @param array  $language_map
	 *
	 * @return void
	 * @throws Exception
	 */
	private function insertProductCategories(string $db_prefix, int $product_id, array $payload, array $language_map): void
	{
		$categories = $payload['categories'] ?? [];

		if (!is_array($categories) || $categories === []) {
