	}

	private function insertCustomerGroupPrices(string $db_prefix, string $table, int $product_id, mixed $rows, bool $is_special): void
	{
		if (!is_array($rows) || $rows === []) {
			return;
		}

		$values       = [];
		$bind_params  = [];
		$placeholders = $is_special ? '(?, ?, ?, ?, ?, ?)' : '(?, ?, ?, ?, ?, ?, ?)';
		foreach ($rows as $row) {
			if (!is_array($row)) {
				continue;
			}

			$customer_group_id = max(0, (int)($row['user_group_id'] ?? 0));
			$values[] = $placeholders;
			$bind_params = array_merge($bind_params, [
				$product_id,
				$customer_group_id,
				(int)($row['priority'] ?? 1),
				(float)($row['price'] ?? 0),
				$this->normalizeDate((string)($row['date_start'] ?? '')),
				$this->normalizeDate((string)($row['date_end'] ?? '')),
			]);

			if (!$is_special) {
				$bind_params[] = max(0, (int)($row['quantity'] ?? 0));
			}
		}

		if ($values === []) {
			return;
		}

		$columns = $is_special
			? '`product_id`, `customer_group_id`, `priority`, `price`, `date_start`, `date_end`'
			: '`product_id`, `customer_group_id`, `priority`, `price`, `date_start`, `date_end`, `quantity`';
		$this->db->safeQuery(
			'INSERT INTO ' . $db_prefix . $table . ' (' . $columns . ') VALUES ' . implode(', ', $values),
			$bind_params
		);
	}

	/**
	 * @param string $value
	 *
	 * @return string
	 */
	private function normalizeText(string $value): string
	{
		return decode_html_entities(trim($value));
	}

	/**
	 * @param string $code
	 *
	 * @return string
	 */
	private function normalizeLanguageCode(string $code): string
	{
		$code = oc_strtolower(trim($code));

		if ($code === '') {
			return '';
		}

		return str_replace('_', '-', $code);
	}

	/**
	 * @param string $date_value
	 *
	 * @return string
	 */
	private function normalizeDate(string $date_value): string
	{
		$date_value = trim($date_value);

		if ($date_value === '' || $date_value === '0000-00-00') {
			return date('Y-m-d');
		}

		if (preg_match('/^\d{4}-\d{2}-\d{2}/', $date_value) === 1) {
			return substr($date_value, 0, 10);
		}

		$timestamp = strtotime($date_value);

		if ($timestamp === false) {
			return date('Y-m-d');
		}

		return date('Y-m-d', $timestamp);
	}

	private function normalizeDateTime(string $date_value): string
	{
		$date_value = trim($date_value);
		if ($date_value === '' || str_starts_with($date_value, '0000-00-00')) {
			return date('Y-m-d H:i:s');
		}

		$timestamp = strtotime($date_value);
		if ($timestamp === false) {
			return date('Y-m-d H:i:s');
		}

		return date('Y-m-d H:i:s', $timestamp);
	}
