namespace Opencart\System\Library\Dto\Db;

class QueryDto
{
	public function __construct(
		public mixed $row = [],
		public array $rows = [],
		public int   $num_rows = 0
	) {
	}

	/**
	 * @param int|string $key
	 * @param mixed      $value
	 *
	 * @return $this
	 */
	public function setRow(int|string $key, mixed $value): QueryDto
	{
		$this->row[$key] = $value;

		return $this;
	}

	/**
	 * @param array $rows
	 *
	 * @return $this
	 */
	public function setRows(array $rows): QueryDto
	{
		$this->rows = $rows;

		return $this;
	}

	/**
	 * @param int $num_rows
	 *
	 * @return $this
	 */
	public function setNumRows(int $num_rows): QueryDto
	{
		$this->num_rows = $num_rows;

		return $this;
	}

	/**
	 * @param int|string|null $key
	 *
	 * @return mixed
	 */
	public function getRow(null|int|string $key = null): mixed
	{
		if ($key !== null && $key !== '') {
			return $this->row[$key] ?? null;
		}

		return $this->row;
	}

	/**
	 * @return array
	 */
	public function getRows(): array
	{
		return $this->rows;
	}

	/**
	 * @return int
	 */
	public function getNumRows(): int
	{
		return $this->num_rows;
	}

	/**
	 * @param string|int $key
	 *
	 * @return bool
	 */
	public function hasInRow(string|int $key): bool
	{
		return isset($this->row[$key]);
	}

	/**
	 * @return void
	 */
	public function clearRows(): void
	{
		$this->rows = [];
	}
