{
	/**
	 * @param string $username
	 * @param string $key
	 *
	 * @return array
	 * @throws Exception
	 */
	public function login(string $username, string $key): array
	{
		$sql = "
			SELECT * FROM `{$this->db_prefix}api` 
				WHERE `username` = ? 
					AND `key` = ? 
					AND `status` = 1
		";

		$query = $this->db->safeQuery($sql, [
			$username,
			$key,
		]);

		return $query->getRow();
	}

	/**
	 * @param int|string $api_id
	 * @param string     $session_id
	 * @param string     $ip
	 *
	 * @return int
	 * @throws Exception
	 */
	public function addSession(int|string $api_id, string $session_id, string $ip): int
	{
		$sql = "
			INSERT INTO `" . env('DB_PREFIX') . "api_session` 
				SET `api_id` = ?, 
					`session_id` = ?, 
					`ip` = ?, 
					`date_added` = ?, 
					`date_modified` = ?
		";

		$this->db->safeQuery($sql, [
			(int)$api_id,
			$session_id,
			$ip,
			date('Y-m-d H:i:s'),
			date('Y-m-d H:i:s'),
		]);

		return (int)$this->db->getLastId();
	}

	/**
	 * @param int $api_id
	 *
	 * @return array
	 * @throws Exception
	 */
	public function getIps(int $api_id): array
	{
		$sql = "
			SELECT * FROM `{$this->db_prefix}api_ip` 
				WHERE `api_id` = ?
		";

