		return $query->getRows();
	}

	/**
	 * @param string $api_token
	 *
	 * @return string
	 * @throws Exception
	 */
	public function getApiIdFromApiSession(string $api_token): string
	{
		$sql = "
			SELECT `api_id` FROM `{$this->db_prefix}api_session` 
				WHERE `session_id` = ?
		";

		$query = $this->db->safeQuery($sql, $api_token);

		return ($query->getRow('api_id') ?? '');
	}
