    public static function syncCategoryAdditionalData(Category $category, array $data): void
    {
        $category_name = trim((string) Arr::get($data, 'category_name', ''));

        if ($category_name !== '') {
            CategoryDescription::query()->updateOrCreate(
                [
                    'category_id'      => (int) $category->id,
                    'shop_language_id' => null,
                ],
                [
                    'name'             => $category_name,
                    'description'      => null,
                    'h1_title'         => $category_name,
                    'meta_title'       => $category_name,
                    'meta_description' => null,
                    'meta_keywords'    => null,
                ],
            );
        }

        $shop_bindings = collect(Arr::get($data, 'shop_bindings', []))
            ->filter(static fn (mixed $shop_binding): bool => is_array($shop_binding))
            ->mapWithKeys(static function (array $shop_binding): array {
                $shop_id = (int) Arr::get($shop_binding, 'shop_id', 0);

                if ($shop_id <= 0) {
                    return [];
                }

                $external_category_id = Arr::get($shop_binding, 'external_category_id');

                return [$shop_id => [
                    'external_category_id' => is_numeric($external_category_id) && (int) $external_category_id > 0
                        ? (int) $external_category_id
                        : null,
                ]];
            })
            ->all();

        $category->shops()->sync($shop_bindings);
    }

    /**
     * @param  array<string, mixed>  $data
     * @return list<int>
     */
    public static function getSelectedShopIds(array $data): array
    {
        return collect(Arr::get($data, 'shop_bindings', []))
            ->filter(static fn (mixed $shop_binding): bool => is_array($shop_binding))
            ->map(static fn (array $shop_binding): int => (int) Arr::get($shop_binding, 'shop_id', 0))
            ->filter(static fn (int $shop_id): bool => $shop_id > 0)
            ->unique()
            ->values()
            ->all();
    }
}
                })
                ->modalSubmitActionLabel(__('admin/categories/categories.delete.modal_confirm')),
        ];
    }

    protected function mutateFormDataBeforeFill(array $data): array
    {
        if ($this->record instanceof Category) {
            $data['category_name'] = (string) ($this->record->descriptions()->orderByRaw('shop_language_id IS NULL DESC')->value('name') ?? '');
            $data['shop_bindings'] = $this->record->categoryShops()
                ->orderBy('shop_id')
                ->get(['shop_id', 'external_category_id'])
                ->map(static fn (CategoryShop $category_shop): array => [
                    'shop_id'              => (int) $category_shop->shop_id,
                    'external_category_id' => $category_shop->external_category_id,
                ])
                ->all();
        }

        return $data;
    }

    protected function handleRecordUpdate(Model $record, array $data): Model
    {
        /** @var Category $category */
        $category = $record;

        $category->update([
            'parent_id'  => Arr::get($data, 'parent_id'),
            'sort_order' => (int) Arr::get($data, 'sort_order', 0),
            'is_active'  => (bool) Arr::get($data, 'is_active', true),
        ]);

        CategoryForm::syncCategoryAdditionalData($category, $data);
        ProcessCategoryNameTranslationJob::dispatch(
            (int) $category->id,
            CategoryForm::getSelectedShopIds($data),
        );

        return $category;
    }
}
