    if (! $this->isInvalidOpenCartAuthTokenResponse($response)) {
        return $response;
    }

    $refreshed_auth_api_token = REDACTED, $api_base_url, $timeout);
    $this->persistOpenCartAuthApiToken($shop, $refreshed_auth_api_token);

