            }

            $is_bound_to_shop = ProductShop::isProductBoundToShop($product_id, $shop_id);

            if (! $is_bound_to_shop) {
                throw new RuntimeException('Product is not bound to selected shop');
            }

            $request_payload = $this->buildRequestPayload($product, $shop_id);
            Log::channel('daily')->info('Prepared export payload with shop-scoped catalog entities', [
                'product_id'        => $product_id,
                'shop_id'           => $shop_id,
                'category_ids'      => collect(Arr::get($request_payload, 'categories', []))->pluck('id')->map(static fn ($id): int => (int) $id)->values()->all(),
                'attribute_ids'     => collect(Arr::get($request_payload, 'attributes', []))->pluck('attribute_id')->map(static fn ($id): int => (int) $id)->values()->all(),
                'manufacturer_id'   => (int) (Arr::get($request_payload, 'manufacturer_brand.manufacturer_id') ?? 0),
                'brand_id'          => (int) (Arr::get($request_payload, 'manufacturer_brand.brand_id') ?? 0),
                'shop_language_ids' => collect(Arr::get($request_payload, 'shop_languages', []))->pluck('id')->map(static fn ($id): int => (int) $id)->values()->all(),
            ]);
            $response = $this->sendExportRequest($shop, $request_payload);

            if (! $response->successful()) {
                throw new RuntimeException($this->buildFailedApiResponseMessage('Export API', $response));
            }

            $response_data       = $response->json();
            $external_product_id = $this->resolveExternalProductIdFromResponse($response_data);

            if ($external_product_id <= 0) {
                throw new RuntimeException('Export API response does not contain external product id');
            }

            ProductShop::updateExternalProductId($product_id, $shop_id, $external_product_id);

            $product_export_item->update([
                'status'        => ProductExportItemsStatusEnum::EXPORTED->value,
                'error_message' => null,
                'processed_at'  => now(),
                'payload'       => [
                    ...$payload,
                    'request_payload'     => $request_payload,
                    'response_status'     => $response->status(),
                    'response_body'       => $this->truncateResponseBody($response->body()),
                    'external_product_id' => $external_product_id,
                ],
            ]);
        } catch (Throwable $exception) {
            Log::channel('stack')->error('Failed to export product with id ' . $product_id . ' for shop with id ' . $shop_id, [
                'error_msg'  => $exception->getMessage(),
                'file'       => $exception->getFile(),
                'line'       => $exception->getLine(),
                'product_id' => $product_id,
                'shop_id'    => $shop_id,
            ]);

            $product_export_item->update([
                'status'        => ProductExportItemsStatusEnum::FAILED->value,
                'error_message' => Str::limit(Str::trim($exception->getMessage()), 10000),
                'processed_at'  => now(),
                    ->state(static fn (ProductImportItem $record): string => (string) ($record->product?->productToManufacturerBrand?->brand?->brand_name ?? ''))
                    ->toggleable(isToggledHiddenByDefault: true),
                TextColumn::make('external_product_id')
                    ->label('External product id')
                    ->state(static function (ProductImportItem $record): string {
                        $product_id = (int) ($record->product_id ?? 0);
                        $batch_id   = (int) ($record->product_import_batch_id ?? 0);

                        if ($product_id <= 0 || $batch_id <= 0) {
                            return '';
                        }

                        return implode(', ', ProductShop::resolveExternalProductIds($product_id, $batch_id));
                    })
                    ->toggleable(),
                TextColumn::make('export_status')
                    ->label(__('admin/product_imports/batches.columns.export_status'))
                    ->state(fn (ProductImportItem $record): string => $this->resolveExportStatus($record))
                    ->badge()
                    ->colors([
                        'gray'    => fn (string $state): bool => $state === ProductImportItemsStatusEnum::NOT_QUEUED->value,
                        'warning' => fn (string $state): bool => $state === ProductExportItemsStatusEnum::PROCESSING->value,
                        'success' => fn (string $state): bool => $state === ProductExportItemsStatusEnum::EXPORTED->value,
                        'danger'  => fn (string $state): bool => in_array($state, [
                            ProductExportItemsStatusEnum::FAILED->value,
                            ProductExportItemsStatusEnum::PARTIAL_FAILED->value,
                        ], true),
                    ])
                    ->formatStateUsing(fn (string $state): string => __('admin/product_imports/batches.export_item_statuses.'.$state)),
                TextColumn::make('bound_shops')
                    ->label(__('admin/product_imports/batches.columns.bound_shops'))
                    ->wrap()
                    ->getStateUsing(function (ProductImportItem $record): string {
                        $product_id = (int) ($record->product_id ?? 0);
                        $batch_id   = (int) ($record->product_import_batch_id ?? 0);

                        if ($product_id <= 0 || $batch_id <= 0) {
                            return __('admin/product_imports/batches.messages.no_bound_shops');
                        }

                        $shop_names = ProductShop::resolveBoundShopNames($product_id, $batch_id);

                        if ($shop_names === []) {
                            return __('admin/product_imports/batches.messages.no_bound_shops');
                        }

                        return implode(', ', $shop_names);
                    }),
                TextColumn::make('payload.source_meta.row_number')
                    ->label(__('admin/product_imports/batches.columns.source_row'))
                    ->getStateUsing(fn (ProductImportItem $record): string => (string) ($record->getSourceRowNumber() ?? __('admin/product_imports/batches.columns.empty_value')))
"}}}

