  # Default: .ai-factory/specs/
  specs: .ai-factory/specs/

  # Rules directory
  # Default: .ai-factory/rules/
  rules: .ai-factory/rules/

  # QA artifacts root directory
  # /aif-qa stores change-summary, test-plan, and test-cases here.
  # /aif-qa-check stores qa-check.md here and binds execution results to
  # the tested revision/build identifier plus deterministic test-cases
  # digests.
  # /aif-qa-check agent also stores root-level agent-context.md and
  # agent-history.md with non-sensitive cross-QA setup facts and
  # recurring learnings; per-run details stay in branch qa-check.md.
  # Both commands use the same deterministic, filesystem-safe derived
  # branch slug as a subdirectory: <qa>/<branch-slug>/
  # The slug uses mandatory 40-character safe-slug truncation plus a short
  # hash suffix for collision resistance (see skills/aif-qa/SKILL.md for
  # the exact algorithm).
  # Default: .ai-factory/qa/
  qa: .ai-factory/qa/

  # Archive directory for completed plans and roadmap snapshots.
  # /aif-archive moves finished plans here (retaining original filenames,
  # including any sequential NNNN_ prefix). Subdirectories:
  #   archive/plans/   — archived plan files
  #   archive/roadmap/ — dated roadmap snapshots
  # Referenced by /aif-archive (owner), /aif-plan, /aif-implement,
  # /aif-verify, /aif-improve.
  # Default: .ai-factory/archive/
  archive: .ai-factory/archive/

# =============================================================================
# Workflow Settings
